const HouseholdIcon = ({ size }) => (
  <Image
    source={require('../assets/images/home_service_household.png')}
    style={{ width: size * 0.6, height: size * 0.6 }}
    resizeMode="contain"
  />
);

const CAROUSEL_SLIDES = [
  require('../assets/images/home_carousel_drycleaning.png'),
  require('../assets/images/home_carousel_shoecare.png'),
  require('../assets/images/home_carousel_cleanclothes.png'),
];

const ALL_SERVICES = [
  { name: 'Dry Cleaning', variant: 'blue', smallIcon: SmallDryCleaningIcon, largeIcon: LargeDryCleaningIcon },
  { name: 'Shoe Care', variant: 'green', smallIcon: SmallShoeCareIcon, largeIcon: LargeShoeCareIcon },
  { name: 'Bag Care', variant: 'blue', smallIcon: SmallBagCareIcon, largeIcon: LargeBagCareIcon },
  { name: 'Toy Care', variant: 'green', smallIcon: ToyCareIcon, largeIcon: LargeToyCareIcon },
  { name: 'Premium Laundry', variant: 'blue', smallIcon: PremiumLaundryIcon, largeIcon: PremiumLaundryIcon },
  { name: 'Household', variant: 'green', smallIcon: HouseholdIcon, largeIcon: HouseholdIcon },
];

const ServiceCard = ({ size, variant, Icon, label, onPress, selected }) => {
  const isGrid = size === 'grid';
  const borderColor = selected
    ? COLORS.accent
    : variant === 'blue'
    ? COLORS.homeServiceCardBorderBlue
    : COLORS.homeServiceCardBorderGreen;
  const circleColor =
    variant === 'blue' ? COLORS.homeServiceCardCircleBlue : COLORS.homeServiceCardCircleGreen;
  const iconSize = isGrid ? HOME.gridCardIconSize : HOME.smallCardIconSize;

  return (
    <TouchableOpacity
      style={[
        styles.serviceCard,
        {
          height: isGrid ? HOME.gridCardHeight : HOME.smallCardHeight,
          borderRadius: isGrid ? HOME.gridCardRadius : HOME.smallCardRadius,
          borderColor,
          borderWidth: selected ? HOME.smallCardSelectedBorderWidth : HOME.serviceCardBorderWidth,
        },
        isGrid ? styles.serviceCardGrid : styles.serviceCardSmall,
      ]}
      onPress={onPress}
    >
      <View
        style={[
          styles.serviceCardCircle,
          {
            width: iconSize,
            height: iconSize,
            borderRadius: iconSize / 2,
            backgroundColor: circleColor,
            marginTop: isGrid ? HOME.gridCardIconMarginTop : HOME.smallCardIconMarginTop,
          },
        ]}
      >
        <Icon size={iconSize} />
      </View>
      <Text style={[styles.serviceCardLabel, !isGrid && styles.serviceCardLabelSmall]}>
        {label}
      </Text>
    </TouchableOpacity>
  );
};

const OrderCard = ({
  accentColor,
  orderNumber,
  subtitle,
  statusBg,
  statusText,
  statusLabel,
  captionLabel,
  captionValue,
}) => (
  <View style={styles.orderCard}>
    <View style={[styles.orderAccentBar, { backgroundColor: accentColor }]} />
    <View style={styles.orderLeft}>
      <Text style={styles.orderIdLabel}>ORDER ID</Text>
      <Text style={styles.orderNumber}>{orderNumber}</Text>
      <View style={styles.orderDashedLine} />
      <Text style={styles.orderSubtitle}>{subtitle}</Text>
    </View>
    <View style={styles.orderDivider} />
    <View style={styles.orderRight}>
      <View style={[styles.statusPill, { backgroundColor: statusBg }]}>
        <Text style={[styles.statusPillText, { color: statusText }]}>{statusLabel}</Text>
      </View>
      <Text style={styles.captionLabel}>{captionLabel}</Text>
      <Text style={styles.captionValue}>{captionValue}</Text>
    </View>
  </View>
);

const HomeScreen = ({
  location = 'New Delhi',
  onOpenProfile = () => {},
  onSelectService = () => {},
  onSchedulePickup = () => {},
  onClaimOffer = () => {},
  onSeeAllServices = () => {},
  onViewAllOrders = () => {},
  onNavigateOrders = () => {},
  onNavigateServices = () => {},
  onNavigateProfile = () => {},
}) => {
  const [activeSlide, setActiveSlide] = useState(0);
  const [carouselWidth, setCarouselWidth] = useState(0);
  const [selectedServices, setSelectedServices] = useState([]);

  const handleCarouselLayout = event => {
    setCarouselWidth(event.nativeEvent.layout.width);
  };

  const handleCarouselScroll = event => {
    if (!carouselWidth) return;
    const index = Math.round(event.nativeEvent.contentOffset.x / carouselWidth);
    setActiveSlide(index);
  };

  const handleSelectService = name => {
    setSelectedServices(prev =>
      prev.includes(name) ? prev.filter(item => item !== name) : [...prev, name],
    );
  };

  return (
    <View style={styles.container}>
      <Svg style={styles.backgroundGradient} height={HOME.backgroundGradientHeight}>
        <Defs>
          <LinearGradient id="homeBg" x1="0%" y1="0%" x2="12%" y2="100%">
            <Stop offset="0%" stopColor={COLORS.loginGradientTop} />
            <Stop offset="70%" stopColor={COLORS.loginGradientBottom} />
          </LinearGradient>
        </Defs>
        <Rect x="0" y="0" width="100%" height="100%" fill="url(#homeBg)" />
      </Svg>

      <View style={styles.header}>
        <View style={styles.headerLeft}>
          <LocationIcon />
          <View>
            <Text style={styles.locationLabel}>Current Location</Text>
            <Text style={styles.locationValue}>{location}</Text>
          </View>
        </View>
        <TouchableOpacity onPress={onOpenProfile}>
          <ProfileIcon />
        </TouchableOpacity>
      </View>

      <ScrollView
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.scrollContent}
      >
        <View style={styles.carouselWrapper} onLayout={handleCarouselLayout}>
          {carouselWidth > 0 && (
            <ScrollView
              horizontal
              pagingEnabled
              showsHorizontalScrollIndicator={false}
              onMomentumScrollEnd={handleCarouselScroll}
            >
              {CAROUSEL_SLIDES.map((slide, index) => (
                <Image
                  key={index}
                  source={slide}
                  style={[styles.carouselImage, { width: carouselWidth }]}
                  resizeMode="cover"
                />
              ))}
            </ScrollView>
          )}
          <View style={styles.dotsRow}>
            {CAROUSEL_SLIDES.map((_, index) => (
              <View
                key={index}
                style={[
                  styles.dot,
                  index === activeSlide ? styles.dotActive : styles.dotInactive,
                ]}
              />
            ))}
          </View>
        </View>

        <View style={styles.section}>
          <View style={styles.centeredHeadingWrapper}>
            <Text style={styles.centeredHeading}>Select Service</Text>
            <View style={styles.underline} />
          </View>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.smallCardsRow}
          >
            {ALL_SERVICES.map(service => (
              <ServiceCard
                key={service.name}
                size="small"
                variant={service.variant}
                Icon={service.smallIcon}
                label={service.name}
                selected={selectedServices.includes(service.name)}
                onPress={() => handleSelectService(service.name)}
              />
            ))}
          </ScrollView>
        </View>

        <TouchableOpacity onPress={() => onSchedulePickup(selectedServices)} style={styles.scheduleButton}>
          <Svg style={StyleSheet.absoluteFill} width="100%" height="100%">
            <Defs>
              <LinearGradient id="scheduleGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                <Stop offset="0%" stopColor={COLORS.homeScheduleGradientStart} />
                <Stop offset="100%" stopColor={COLORS.homeScheduleGradientEnd} />
              </LinearGradient>
            </Defs>
            <Rect x="0" y="0" width="100%" height="100%" fill="url(#scheduleGradient)" />
          </Svg>
          <Text style={styles.scheduleButtonText}>Schedule Pickup</Text>
          <ArrowIcon />
        </TouchableOpacity>

        <TouchableOpacity onPress={onClaimOffer}>
          <Image
            source={require('../assets/images/home_offer_banner.png')}
            style={styles.offerBanner}
            resizeMode="cover"
          />
        </TouchableOpacity>

        <View style={styles.section}>
          <View style={styles.sectionHeaderRow}>
            <Text style={styles.sectionHeading}>Our Services</Text>
            <TouchableOpacity onPress={onSeeAllServices}>
              <Text style={styles.seeAllLink}>See All</Text>
            </TouchableOpacity>
          </View>

          <View style={styles.gridRow}>
            <ServiceCard
              size="grid"
              variant="blue"
              Icon={LargeDryCleaningIcon}
              label="Dry Cleaning"
              onPress={() => onSelectService('Dry Cleaning')}
            />
            <ServiceCard
              size="grid"
              variant="green"
              Icon={LargeShoeCareIcon}
              label="Shoe Care"
              onPress={() => onSelectService('Shoe Care')}
            />
          </View>
          <View style={styles.gridRow}>
            <ServiceCard
              size="grid"
              variant="green"
              Icon={LargeBagCareIcon}
              label="Bag Care"
              onPress={() => onSelectService('Bag Care')}
            />
            <ServiceCard
              size="grid"
              variant="blue"
              Icon={LargeToyCareIcon}
              label="Toy Care"
              onPress={() => onSelectService('Toy Care')}
            />
          </View>
        </View>

        <View style={styles.section}>
          <View style={styles.sectionHeaderRow}>
            <Text style={styles.sectionHeading}>Recent Orders</Text>
            <TouchableOpacity onPress={onViewAllOrders}>
              <Text style={styles.seeAllLink}>View All</Text>
            </TouchableOpacity>
          </View>

          <View style={styles.ordersList}>
            <OrderCard
              accentColor={COLORS.homeOrderAccentInProgress}
              orderNumber="#4829"
              subtitle="Wash & Fold • 3items"
              statusBg={COLORS.homeStatusInProgressBg}
              statusText={COLORS.homeStatusInProgressText}
              statusLabel="In Progress"
              captionLabel="Expected"
              captionValue="Tomorrow"
            />
            <OrderCard
              accentColor={COLORS.homeOrderAccentDelivered}
              orderNumber="#4810"
              subtitle="Dry Cleaning • 2 items"
              statusBg={COLORS.homeStatusDeliveredBg}
              statusText={COLORS.homeStatusDeliveredText}
              statusLabel="Delivered"
              captionLabel="Delivered on"
              captionValue="Oct 12"
            />
          </View>
        </View>
      </ScrollView>

      <BottomNavBar
        activeTab="Home"
        onNavigateOrders={onNavigateOrders}
        onNavigateServices={onNavigateServices}
        onNavigateProfile={onNavigateProfile}
      />
    </View>
  );
};

